1	// In-process, time bounded lease registry with append-only log persistence
2	// and crash-safe snapshots. Time only moves when the injected clock moves;
3	// nothing expires on its own. Tokens are derived from the injected clock as
4	// well, never from wall time.
5	//
6	// Persistence layout:
7	//   <logPath>           append-only event log, one JSON object per line
8	//   <logPath>.snapshot  last compacted state image (single JSON line)
9	// Startup loads the snapshot (if any) and replays only the events past the
10	// compacted boundary marker. Compaction publishes both files through a
11	// temp-file + fsync + rename sequence, so a failure at any step leaves the
12	// previous snapshot and the previous log usable. Every event carries a
13	// monotonic sequence number; a snapshot found next to an un-exchanged
14	// original log (the log swap died after the snapshot rename) simply skips
15	// the already-folded events by their sequence ids, so each event applies
16	// exactly once regardless of which rename made it to disk.
17	
18	import fs from 'node:fs';
19	import path from 'node:path';
20	
21	const LOG_VERSION = 1;
22	const SNAPSHOT_VERSION = 1;
23	
24	export class LeaseTakenError extends Error {
25	  constructor(resource, holder) {
26	    super(`lease for resource ${String(resource)} is already held`);
27	    this.name = 'LeaseTakenError';
28	    this.code = LeaseTakenError.code;
29	    this.resource = resource;
30	    this.holder = holder ?? null;
31	  }
32	}
33	LeaseTakenError.code = 'LEASE_TAKEN';
34	
35	export class LogFileError extends Error {
36	  constructor(message, cause) {
37	    super(message);
38	    this.name = 'LogFileError';
39	    this.code = LogFileError.code;
40	    this.cause = cause ?? null;
41	  }
42	}
43	LogFileError.code = 'LOG_FILE_ERROR';
44	
45	// Binary min-heap ordered by (expiresAt, insertion order). Every live lease
46	// has a node in the queue; renewals push a fresh node and retire the old one,
47	// so reclaiming expired leases only walks entries that are actually due
48	// instead of scanning the whole table.
49	class ExpiryQueue {
50	  constructor() {
51	    this.nodes = [];
52	  }
53	
54	  get size() {
55	    return this.nodes.length;
56	  }
57	
58	  push(node) {
59	    const nodes = this.nodes;
60	    nodes.push(node);
61	    let i = nodes.length - 1;
62	    while (i > 0) {
63	      const parent = (i - 1) >> 1;
64	      if (expiresBefore(nodes[i], nodes[parent])) {
65	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
66	        i = parent;
67	      } else {
68	        break;
69	      }
70	    }
71	  }
72	
73	  peek() {
74	    return this.nodes[0];
75	  }
76	
77	  pop() {
78	    const nodes = this.nodes;
79	    const top = nodes[0];
80	    const last = nodes.pop();
81	    if (nodes.length > 0) {
82	      nodes[0] = last;
83	      let i = 0;
84	      for (;;) {
85	        const left = i * 2 + 1;
86	        const right = left + 1;
87	        let next = i;
88	        if (left < nodes.length && expiresBefore(nodes[left], nodes[next])) {
89	          next = left;
90	        }
91	        if (right < nodes.length && expiresBefore(nodes[right], nodes[next])) {
92	          next = right;
93	        }
94	        if (next === i) {
95	          break;
96	        }
97	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
98	        i = next;
99	      }
100	    }
101	    return top;
102	  }
103	}
104	
105	function expiresBefore(a, b) {
106	  if (a.expiresAt !== b.expiresAt) {
107	    return a.expiresAt < b.expiresAt;
108	  }
109	  return a.order < b.order;
110	}
111	
112	// Binary min-heap of wait-request deadlines. Timeout cleanup pops due
113	// requests in deadline order instead of scanning every pending request, so
114	// a large waiting population costs O(expired * log n), never O(n) per call.
115	class DeadlineQueue {
116	  constructor() {
117	    this.nodes = [];
118	  }
119	
120	  get size() {
121	    return this.nodes.length;
122	  }
123	
124	  push(node) {
125	    const nodes = this.nodes;
126	    nodes.push(node);
127	    let i = nodes.length - 1;
128	    while (i > 0) {
129	      const parent = (i - 1) >> 1;
130	      if (deadlineBefore(nodes[i], nodes[parent])) {
131	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
132	        i = parent;
133	      } else {
134	        break;
135	      }
136	    }
137	  }
138	
139	  peek() {
140	    return this.nodes[0];
141	  }
142	
143	  pop() {
144	    const nodes = this.nodes;
145	    const top = nodes[0];
146	    const last = nodes.pop();
147	    if (nodes.length > 0) {
148	      nodes[0] = last;
149	      let i = 0;
150	      for (;;) {
151	        const left = i * 2 + 1;
152	        const right = left + 1;
153	        let next = i;
154	        if (left < nodes.length && deadlineBefore(nodes[left], nodes[next])) {
155	          next = left;
156	        }
157	        if (right < nodes.length && deadlineBefore(nodes[right], nodes[next])) {
158	          next = right;
159	        }
160	        if (next === i) {
161	          break;
162	        }
163	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
164	        i = next;
165	      }
166	    }
167	    return top;
168	  }
169	}
170	
171	function deadlineBefore(a, b) {
172	  if (a.deadline !== b.deadline) {
173	    return a.deadline < b.deadline;
174	  }
175	  return a.tie < b.tie;
176	}
177	
178	let registrySequence = 0;
179	let atomicFileSequence = 0;
180	
181	export function createRegistry({ ttlMs, clock = Date.now, logPath = null } = {}) {
182	  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
183	    throw new TypeError('ttlMs must be a positive finite number');
184	  }
185	  if (typeof clock !== 'function') {
186	    throw new TypeError('clock must be a function');
187	  }
188	
189	  const snapshotPath = logPath === null ? null : `${logPath}.snapshot`;
190	  const defaultTtlMs = ttlMs;
191	  // resource -> FIFO array of queue positions. A group request listing the
192	  // same resource twice occupies two consecutive positions in that queue.
193	  const waitQueues = new Map();
194	  // requestId -> group, while the request is still queued.
195	  const pendingGroups = new Map();
196	  // token -> { resource, holder, expiresAt, ttlMs, legacy, heapSeq }
197	  const leases = new Map();
198	  // Every token this instance knows about, including replayed credentials
199	  // that were already released or reclaimed, so a freshly minted token can
200	  // never reuse a dead credential's string.
201	  const knownTokens = new Set();
202	  // resource -> tokens currently occupying it. Usually one entry; an atomic
203	  // group listing one resource several times holds one credential per
204	  // occurrence, all belonging to the same request.
205	  const slots = new Map();
206	  const expiryQueue = new ExpiryQueue();
207	  // One node per queued wait request, ordered by wait deadline. Nodes outlive
208	  // their request only until the next lazy pop, flagged `dead`.
209	  const deadlineQueue = new DeadlineQueue();
210	
211	  const counters = {
212	    granted: 0,
213	    renewed: 0,
214	    released: 0,
215	    reclaimed: 0,
216	  };
217	
218	  // Per-instance identity makes tokens unique across registries living in the
219	  // same process; one instance can never present a token another owns.
220	  registrySequence += 1;
221	  const registryId = registrySequence;
222	  let tokenSequence = 0;
223	  let queueOrder = 0;
224	  let deadlineTie = 0;
225	  let requestSequence = 0;
226	  let batchSequence = 0;
227	  // Monotonic id stamped on every persisted event; a snapshot records the
228	  // last id it folded in, so a log still containing the folded prefix (the
229	  // log swap failed) replays those events as no-ops instead of twice.
230	  let eventSeq = 0;
231	
232	  function mintToken(now, seq = tokenSequence) {
233	    // Pure candidate: nothing is committed until the event is on disk, so a
234	    // failed append rolls all the way back. Pids and instance ids can coincide
235	    // after a restart, so skip any sequence that collides with a credential
236	    // reconstructed from the log. The caller threads the sequence through when
237	    // it mints several tokens for one atomic write.
238	    let token;
239	    do {
240	      seq += 1;
241	      token = `lease-${process.pid}-${registryId}-${seq}-${now.toString(36)}`;
242	    } while (knownTokens.has(token));
243	    return { token, seq };
244	  }
245	
246	  function enqueue(token, lease) {
247	    expiryQueue.push({
248	      token,
249	      expiresAt: lease.expiresAt,
250	      heapSeq: lease.heapSeq,
251	      order: queueOrder++,
252	    });
253	  }
254	
255	  function isLive(lease, now) {
256	    return lease !== undefined && lease.expiresAt > now;
257	  }
258	
259	  function getSlots(resource) {
260	    let list = slots.get(resource);
261	    if (list === undefined) {
262	      list = [];
263	      slots.set(resource, list);
264	    }
265	    return list;
266	  }
267	
268	  function addSlot(resource, token) {
269	    getSlots(resource).push(token);
270	  }
271	
272	  function removeSlot(resource, token) {
273	    const list = slots.get(resource);
274	    if (list === undefined) {
275	      return false;
276	    }
277	    const index = list.indexOf(token);
278	    if (index === -1) {
279	      return false;
280	    }
281	    list.splice(index, 1);
282	    if (list.length === 0) {
283	      slots.delete(resource);
284	    }
285	    return true;
286	  }
287	
288	  // Drop expired-but-unswept credentials from a resource that is about to be
289	  // granted: the resource is free, and a retaken lease must never be reported
290	  // as reclaimed later. Mirrors the single-resource retake rule.
291	  function dropStaleSlots(resource, now) {
292	    const list = slots.get(resource);
293	    if (list === undefined) {
294	      return;
295	    }
296	    for (let i = list.length - 1; i >= 0; i -= 1) {
297	      const token = list[i];
298	      if (!isLive(leases.get(token), now)) {
299	        leases.delete(token);
300	        list.splice(i, 1);
301	      }
302	    }
303	    if (list.length === 0) {
304	      slots.delete(resource);
305	    }
306	  }
307	
308	  function liveSlotCount(resource, now) {
309	    const list = slots.get(resource);
310	    if (list === undefined) {
311	      return 0;
312	    }
313	    let live = 0;
314	    for (const token of list) {
315	      if (isLive(leases.get(token), now)) {
316	        live += 1;
317	      }
318	    }
319	    return live;
320	  }
321	
322	  function liveHolder(resource, now) {
323	    const list = slots.get(resource);
324	    if (list === undefined) {
325	      return null;
326	    }
327	    for (const token of list) {
328	      const lease = leases.get(token);
329	      if (isLive(lease, now)) {
330	        return lease.holder;
331	      }
332	    }
333	    return null;
334	  }
335	
336	  function fsyncDirectory(file) {
337	    // Best-effort durability for the rename itself: on platforms where
338	    // fsyncing a directory handle is unsupported there is nothing to sync,
339	    // and the rename has already committed by the time this runs.
340	    try {
341	      const fd = fs.openSync(path.dirname(file), 'r');
342	      try {
343	        fs.fsyncSync(fd);
344	      } finally {
345	        fs.closeSync(fd);
346	      }
347	    } catch {
348	      // Ignored: atomicity of the swap does not depend on it.
349	    }
350	  }
351	
352	  // Publish a file via temp + fsync + rename so the target is either the old
353	  // complete content or the new complete content, never a mixture. Any failure
354	  // leaves the target untouched and surfaces as an assertable LogFileError.
355	  function writeAtomic(target, content) {
356	    atomicFileSequence += 1;
357	    const tmp = `${target}.tmp-${process.pid}-${atomicFileSequence}`;
358	    try {
359	      const fd = fs.openSync(tmp, 'wx');
360	      try {
361	        fs.writeFileSync(fd, content, 'utf8');
362	        fs.fsyncSync(fd);
363	      } finally {
364	        fs.closeSync(fd);
365	      }
366	      fs.renameSync(tmp, target);
367	      fsyncDirectory(target);
368	    } catch (cause) {
369	      try {
370	        fs.rmSync(tmp, { force: true });
371	      } catch {
372	        // The original error is the one the caller must act on.
373	      }
374	      throw new LogFileError(
375	        `failed to write lease file ${target}`,
376	        cause,
377	      );
378	    }
379	  }
380	
381	  function appendEvents(events) {
382	    if (logPath === null) {
383	      return;
384	    }
385	    // One write for the whole batch: an operation that frees resources and
386	    // wakes requests either lands completely or not at all. Sequence ids are
387	    // numbered up front but only committed after the write lands, so a failed
388	    // append leaves both the log and the counter exactly as before.
389	    let text = '';
390	    let seq = eventSeq;
391	    for (const event of events) {
392	      seq += 1;
393	      event.e = seq;
394	      text += `${JSON.stringify(event)}\n`;
395	    }
396	    try {
397	      fs.appendFileSync(logPath, text);
398	    } catch (cause) {
399	      throw new LogFileError(
400	        `failed to append to lease log at ${logPath}`,
401	        cause,
402	      );
403	    }
404	    eventSeq = seq;
405	  }
406	
407	  function appendEvent(event) {
408	    appendEvents([event]);
409	  }
410	
411	  function detachGroup(group) {
412	    for (const position of group.positions) {
413	      const queue = waitQueues.get(position.resource);
414	      if (queue === undefined) {
415	        continue;
416	      }
417	      const index = queue.indexOf(position);
418	      if (index !== -1) {
419	        queue.splice(index, 1);
420	        if (queue.length === 0) {
421	          waitQueues.delete(position.resource);
422	        }
423	      }
424	    }
425	    pendingGroups.delete(group.requestId);
426	    // Its deadline node retires lazily on the next purge.
427	    group.deadlineNode.dead = true;
428	  }
429	
430	  // A queued request gives up once the clock reaches its deadline and is
431	  // never woken afterwards. Only the deadline heap is consulted: requests
432	  // that are still live are never even looked at, no matter how many wait.
433	  function purgeExpiredWaiters(now) {
434	    while (deadlineQueue.size > 0) {
435	      const node = deadlineQueue.peek();
436	      if (node.dead) {
437	        deadlineQueue.pop();
438	        continue;
439	      }
440	      if (node.deadline > now) {
441	        break;
442	      }
443	      deadlineQueue.pop();
444	      const group = pendingGroups.get(node.requestId);
445	      if (group === undefined || group.deadlineNode !== node) {
446	        continue;
447	      }
448	      detachGroup(group);
449	      group.ticket.status = 'expired';
450	    }
451	  }
452	
453	  function enqueueGroup(resources, ttlList, holder, now, waitMs, single) {
454	    requestSequence += 1;
455	    const requestId = `wait-${registryId}-${requestSequence}`;
456	    const ticket = single
457	      // Exact baseline shape for single-resource callers.
458	      ? { status: 'waiting', resource: resources[0], holder, waitId: requestId }
459	      : { status: 'waiting', resources: [...resources], holder, waitId: requestId };
460	    deadlineTie += 1;
461	    const deadlineNode = { requestId, deadline: now + waitMs, tie: deadlineTie, dead: false };
462	    const group = {
463	      requestId,
464	      arrival: requestSequence,
465	      holder,
466	      deadline: now + waitMs,
467	      deadlineNode,
468	      single,
469	      ticket,
470	      positions: [],
471	    };
472	    deadlineQueue.push(deadlineNode);
473	    // One position per listed occurrence, pushed onto each resource's queue
474	    // in the given order. Positions of one request land consecutively, so a
475	    // repeated resource lines up as many times as it was listed.
476	    resources.forEach((resource, index) => {
477	      const position = {
478	        group,
479	        resource,
480	        ttlMs: ttlList[index],
481	        granted: false,
482	        token: null,
483	        expiresAt: null,
484	      };
485	      group.positions.push(position);
486	      let queue = waitQueues.get(resource);
487	      if (queue === undefined) {
488	        queue = [];
489	        waitQueues.set(resource, queue);
490	      }
491	      queue.push(position);
492	    });
493	    pendingGroups.set(requestId, group);
494	    return group;
495	  }
496	
497	  // Plan every grant one request needs (one per still-ungranted position),
498	  // touching no state. The caller commits only after all events are on disk.
499	  // batchId ties the credentials of one atomic batch together for replay.
500	  function planGroupGrants(group, now, seqCursor) {
501	    const batchId = nextBatchId();
502	    const grants = [];
503	    let seq = seqCursor;
504	    for (const position of group.positions) {
505	      if (position.granted) {
506	        continue;
507	      }
508	      const minted = mintToken(now, seq);
509	      seq = minted.seq;
510	      const expiresAt = now + position.ttlMs;
511	      grants.push({
512	        position,
513	        group,
514	        resource: position.resource,
515	        holder: group.holder,
516	        ttlMs: position.ttlMs,
517	        token: minted.token,
518	        seq: minted.seq,
519	        expiresAt,
520	        event: {
521	          v: LOG_VERSION,
522	          type: 'acquire',
523	          at: now,
524	          token: minted.token,
525	          resource: position.resource,
526	          holder: group.holder,
527	          ttlMs: position.ttlMs,
528	          expiresAt,
529	          requestId: group.requestId,
530	          batch: batchId,
531	        },
532	      });
533	    }
534	    return { group, grants, seq, batchId };
535	  }
536	
537	  function applyPlannedGrants(plan, now) {
538	    for (const grant of plan.grants) {
539	      tokenSequence = grant.seq;
540	      knownTokens.add(grant.token);
541	      const lease = {
542	        resource: grant.resource,
543	        holder: grant.holder,
544	        expiresAt: grant.expiresAt,
545	        ttlMs: grant.ttlMs,
546	        legacy: false,
547	        heapSeq: 0,
548	        batch: plan.batchId,
549	      };
550	      leases.set(grant.token, lease);
551	      dropStaleSlots(grant.resource, now);
552	      addSlot(grant.resource, grant.token);
553	      enqueue(grant.token, lease);
554	      counters.granted += 1;
555	
556	      grant.position.token = grant.token;
557	      grant.position.expiresAt = grant.expiresAt;
558	      grant.position.granted = true;
559	    }
560	
561	    // The batch holds everything it asked for; it leaves every queue at once.
562	    const { group } = plan;
563	    const { ticket } = group;
564	    detachGroup(group);
565	    ticket.status = 'granted';
566	    const granted = group.positions.map((position) => ({
567	      resource: position.resource,
568	      holder: group.holder,
569	      token: position.token,
570	      expiresAt: position.expiresAt,
571	    }));
572	    if (group.single) {
573	      ticket.token = granted[0].token;
574	      ticket.expiresAt = granted[0].expiresAt;
575	    } else {
576	      // One credential per listed occurrence, each with its own expiry.
577	      ticket.leases = granted;
578	      // Aliases for callers that read the batch outcome as a flat list.
579	      ticket.results = granted;
580	    }
581	  }
582	
583	  function positionPlanned(plans, position) {
584	    return plans.some((plan) =>
585	      plan.grants.some((grant) => grant.position === position));
586	  }
587	
588	  // A queued request is fillable exactly when every position reaches the
589	  // front of its resource's queue and that resource is free once the
590	  // triggering event is applied. Only live credentials occupy: an expired
591	  // but unswept lease is already gone, while a surviving twin of a released
592	  // duplicate credential keeps the resource held.
593	  function groupFillable(group, plans, freedLiveCount, now) {
594	    for (const position of group.positions) {
595	      if (position.granted) {
596	        continue;
597	      }
598	      const queue = waitQueues.get(position.resource);
599	      if (queue === undefined) {
600	        return false;
601	      }
602	      const index = queue.indexOf(position);
603	      for (let i = 0; i < index; i += 1) {
604	        const ahead = queue[i];
605	        if (ahead.group === group) {
606	          // Own repeated listing: its positions are granted together.
607	          continue;
608	        }
609	        if (positionPlanned(plans, ahead)) {
610	          continue;
611	        }
612	        return false;
613	      }
614	      // A release vacates a live credential; a sweep only removes leases
615	      // that were already expired, so it frees no live occupancy here.
616	      let occupied = Math.max(
617	        0,
618	        liveSlotCount(position.resource, now)
619	          - (freedLiveCount.get(position.resource) ?? 0),
620	      );
621	      for (const plan of plans) {
622	        if (plan.group === group) {
623	          continue;
624	        }
625	        for (const grant of plan.grants) {
626	          if (grant.resource === position.resource) {
627	            occupied += 1;
628	          }
629	        }
630	      }
631	      if (occupied > 0) {
632	        return false;
633	      }
634	    }
635	    return true;
636	  }
637	
638	  // Grant every queued request whose resources become available through the
639	  // given freeing event, cascading across resources and queues. Entries are
640	  // { resource, live }: a release vacates a live credential, a reclaim only
641	  // removes one that had already expired. Everything planned rides in the
642	  // triggering log write.
643	  //
644	  // Only requests standing at the head of a queue touched by the event (plus
645	  // the requests exposed behind a batch planned in this cascade) can possibly
646	  // be fillable: a request was not fillable when it queued, and nothing else
647	  // changed. Wake planning therefore never inspects requests waiting on
648	  // unrelated resources, regardless of how many are queued in total.
649	  function planWakeups(freedEntries, now) {
650	    const freedLiveCount = new Map();
651	    const touched = new Set();
652	    for (const entry of freedEntries) {
653	      touched.add(entry.resource);
654	      if (entry.live) {
655	        freedLiveCount.set(
656	          entry.resource,
657	          (freedLiveCount.get(entry.resource) ?? 0) + 1,
658	        );
659	      }
660	    }
661	    const plans = [];
662	    const planned = new Set();
663	    const candidates = new Set();
664	    const seedHead = (resource) => {
665	      const queue = waitQueues.get(resource);
666	      if (queue !== undefined && queue.length > 0) {
667	        candidates.add(queue[0].group);
668	      }
669	    };
670	    for (const resource of touched) {
671	      seedHead(resource);
672	    }
673	    let seq = tokenSequence;
674	    for (;;) {
675	      // Candidates are picked strictly by arrival order: the earliest
676	      // pending request whose batch is now complete wins, so no resource's
677	      // queue can jump ahead of an earlier request.
