57	});
58	test.afterEach(() => {
59	  fs.rmSync(dir, { recursive: true, force: true });
60	});
61	
62	function snapshotOf(p) {
63	  return `${p}.snapshot`;
64	}
65	
66	// Build a history that exercises every counter and leaves a mix of live,
67	// renewed and expired-but-unswept credentials behind.
68	function buildHistory(p, clock) {
69	  const r = createRegistry({ ttlMs: 100, clock, logPath: p });
70	  const keep = r.acquire('keep', 'h1', 100);
71	  const renewed = r.acquire('renewed', 'h2', 40);
72	  const freed = r.acquire('freed', 'h3', 100);
73	  r.acquire('expired', 'h4', 10);
74	  const group = r.acquireAll(['g1', 'g2'], 'h5', [30, 80]);
75	  clock.set(30);
76	  r.renew(renewed.token);
77	  r.release(freed.token);
78	  clock.set(50);
79	  return { r, keep, renewed, freed, group };
80	}
81	
82	const EXPECTED_STATS = {
83	  // At t=50: keep(100), renewed(->130), g2(80) live; expired(10) and
84	  // g1(30) are expired but unswept; freed was released.
85	  granted: 6, renewed: 1, released: 1, reclaimed: 0, live: 3,
86	};
87	
88	test('compaction publishes a snapshot and a marker, then folds the history', () => {
89	  const p = logPath('basic');
90	  const c = fakeClock(0);
91	  const { r } = buildHistory(p, c);
92	  assert.deepEqual(r.stats(), EXPECTED_STATS);
93	
94	  const result = r.compact();
95	  assert.equal(result.leases, 5);
96	  assert.equal(fs.existsSync(snapshotOf(p)), true);
97	  const logText = fs.readFileSync(p, 'utf8');
98	  assert.equal(logText.trim().split('\n').length, 1);
99	  const marker = JSON.parse(logText);
100	  assert.equal(marker.type, 'snapshot-start');
101	  assert.equal(marker.seq, result.seq);
102	
103	  // Restart from the snapshot alone: ownership and counters come back item
104	  // by item, with no extra counts from the rebuild itself.
105	  const r2 = createRegistry({ ttlMs: 100, clock: fakeClock(50), logPath: p });
106	  assert.equal(r2.holder('keep'), 'h1');
107	  assert.equal(r2.holder('renewed'), 'h2');
108	  assert.equal(r2.holder('freed'), null);
109	  assert.equal(r2.holder('expired'), null);
110	  assert.equal(r2.holder('g1'), null); // expired at 30, unswept
111	  assert.equal(r2.holder('g2'), 'h5');
112	  assert.deepEqual(r2.stats(), EXPECTED_STATS);
