114	  // renewed carries its own ttl of 40: renewed at t=30 moves it from 40 to
115	  // 70. g1 expires 30, g2 80, keep 100.
116	  assert.deepEqual(r2.sweep(50), ['expired', 'g1']);
117	  assert.deepEqual(r2.sweep(69), []);
118	  assert.deepEqual(r2.sweep(70), ['renewed']);
119	  assert.deepEqual(r2.sweep(79), []);
