// 既有行为保持不变：公开入口、单资源与成组获取、续租、提前释放、回收顺序、
// 统计口径、取消语义、时钟倒退按传入读数判定，以及不引入运行期依赖。

import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRegistry, LogFileError, LeaseTakenError } from '../src/index.js';

function makeClock(start = 0) {
  let now = start;
  const clock = () => now;
  clock.set = (value) => {
    now = value;
  };
  return clock;
}

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

// 1. 不引入运行期依赖
const pkg = JSON.parse(fs.readFileSync(path.join(repoRoot, 'package.json'), 'utf8'));
assert.deepEqual(Object.keys(pkg.dependencies || {}), [], '不得引入运行期依赖');

// 2. 公开入口齐全，错误类型照旧导出
const probe = createRegistry({ ttlMs: 100 });
for (const name of ['acquire', 'acquireAll', 'acquireGroup', 'acquireMany', 'renew', 'release', 'sweep', 'holder', 'stats', 'cancel']) {
  assert.equal(typeof probe[name], 'function', '缺少公开方法 ' + name);
}
assert.equal(typeof LogFileError, 'function');
assert.equal(LogFileError.code, 'LOG_FILE_ERROR');
assert.equal(typeof LeaseTakenError, 'function');

// 3. 单资源获取的返回结构、到期时刻与统计口径
const clock = makeClock(0);
const registry = createRegistry({ ttlMs: 100, clock });
const lease = registry.acquire('r1', 'h1', 50);
assert.equal(lease.resource, 'r1');
assert.equal(lease.holder, 'h1');
assert.equal(typeof lease.token, 'string');
assert.equal(lease.expiresAt, 50);
assert.deepEqual(registry.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });

// 4. 续租与提前释放
assert.equal(registry.renew(lease.token), true);
assert.equal(registry.release(lease.token), true);
assert.equal(registry.release(lease.token), false);
assert.equal(registry.renew(lease.token), false);
assert.equal(registry.holder('r1'), null);
assert.deepEqual(registry.stats(), { granted: 1, renewed: 1, released: 1, reclaimed: 0, live: 0 });

// 5. 回收顺序按到期时刻
const sweepClock = makeClock(0);
const sweepRegistry = createRegistry({ ttlMs: 100, clock: sweepClock });
sweepRegistry.acquire('z', 'h', 30);
sweepRegistry.acquire('a', 'h', 10);
sweepRegistry.acquire('m', 'h', 20);
assert.deepEqual(sweepRegistry.sweep(50), ['a', 'm', 'z']);
assert.deepEqual(sweepRegistry.stats(), { granted: 3, renewed: 0, released: 0, reclaimed: 3, live: 0 });

// 6. 成组获取的结构、原子性与别名
const groupClock = makeClock(0);
const groupRegistry = createRegistry({ ttlMs: 100, clock: groupClock });
const pair = groupRegistry.acquireAll(['p', 'q'], 'h1', 10);
assert.equal(pair.length, 2);
assert.equal(pair[0].resource, 'p');
assert.equal(pair[1].resource, 'q');
assert.equal(pair[0].expiresAt, 10);
assert.equal(pair[1].expiresAt, 10);
assert.throws(
  () => groupRegistry.acquire('p', 'h2', 10),
  (error) => error instanceof LeaseTakenError && typeof error.code === 'string',
);
const statsBefore = groupRegistry.stats();
assert.throws(
  () => groupRegistry.acquireAll(['q2', 'p'], 'h3', 10),
  (error) => error instanceof LeaseTakenError && typeof error.code === 'string',
);
assert.deepEqual(groupRegistry.stats(), statsBefore);
assert.equal(groupRegistry.holder('q2'), null);

