function liveHolder(resource, now) {
  // Prune only the heap head: the earliest still-valid node is a live
  // holder once every due node ahead of it is set aside. Due nodes go back
  // verbatim because their shares still await a sweep.
  const heap = slotHeaps.get(resource);
  if (heap === undefined) {
    return null;
  }
  const restore = [];
  let holderName = null;
  while (heap.size > 0) {
    const node = heap.peek();
    const lease = leases.get(node.token);
    if (lease === undefined || lease.heapSeq !== node.heapSeq) {
      heap.pop();
      continue;
    }
    if (node.expiresAt <= now) {
      restore.push(heap.pop());
      continue;
    }
    holderName = lease.holder;
    break;
  }
  for (const node of restore) {
    heap.push(node);
  }
  return holderName;
}

