// Quota nodes one grant on `resource` charges, one entry per ancestor level
// (the resource's own node first), each carrying the share amount.
function quotaPath(resource, shares) {
  const path = [];
  let cur = resourceQuota.get(resource) ?? null;
  const seen = new Set();
  while (cur !== null && !seen.has(cur)) {
    seen.add(cur);
    path.push({ node: cur, amount: shares });
    const def = quotaDefs.get(cur);
    cur = def === undefined ? null : def.parent;
  }
  return path;
}

