// Non-destructive liveness read for a resource that has not been granted
// yet: due nodes are popped only to be pushed straight back, so a failed
// application changes neither the lease table nor the future reclaim count.
function inspectStale(resource, now) {
  const heap = slotHeaps.get(resource);
  const popped = [];
  let shares = 0;
  const quota = new Map();
  if (heap !== undefined) {
    while (heap.size > 0) {
      const node = heap.peek();
      const lease = leases.get(node.token);
      if (lease === undefined || lease.heapSeq !== node.heapSeq) {
        // Retired node: drop it for good, it represents no slot anymore.
        heap.pop();
        continue;
      }
      if (node.expiresAt > now) {
        break;
      }
      heap.pop();
      popped.push(node);
      shares += node.shares;
      if (lease.quotas !== null) {
        for (const { node: qn, amount } of lease.quotas) {
          quota.set(qn, (quota.get(qn) ?? 0) + amount);
        }
      }
    }
    // Live leases' stale nodes go back verbatim: the shares still occupy
    // until a sweep reclaims them, this read must not change that.
    for (const node of popped) {
      heap.push(node);
    }
  }
  return { shares, quota };
}

// Drop retired and expired-but-unswept credentials from a resource whose
// new shares are being committed: the resource is being taken over, and a
// retaken share must never be reported as reclaimed later. Mirrors the
// single-resource retake rule.
function dropStale(resource, now) {
  const heap = slotHeaps.get(resource);
  if (heap === undefined) {
    return;
  }
  while (heap.size > 0) {
    const node = heap.peek();
    const lease = leases.get(node.token);
    if (lease === undefined || lease.heapSeq !== node.heapSeq) {
      heap.pop();
      continue;
    }
    if (node.expiresAt > now) {
      break;
    }
    heap.pop();
    leases.delete(node.token);
    getSlots(resource).delete(node.token);
    presentShares.set(resource, (presentShares.get(resource) ?? 0) - node.shares);
    chargeQuota(lease.quotas, -1);
