// A queued request is fillable exactly when every position reaches the
// front of its resource's queue, every resource has enough committing and
// remaining capacity for the shares the request asks there, and every quota
// level in its ancestry still has room once the triggering frees and the
// grants already planned in this cascade are accounted for. Expired-but-
// unswept shares keep occupying until a sweep reclaims them, exactly as a
// held resource blocks waiters today.
function groupFillable(group, plans, frees) {
  const { freedShares, freedQuota } = frees;
  const needByResource = new Map();
  for (const position of group.positions) {
    if (position.granted) {
      continue;
    }
    const queue = waitQueues.get(position.resource);
    if (queue === undefined) {
      return false;
    }
    const index = queue.indexOf(position);
    for (let i = 0; i < index; i += 1) {
      const ahead = queue[i];
      if (ahead.group === group) {
        // Own repeated listing: its positions are granted together.
        continue;
      }
      if (positionPlanned(plans, ahead)) {
        continue;
      }
      return false;
    }
    // Declared capacity resources account for every requested share; an
    // undeclared resource keeps the single-occupancy presence rule where
    // the request's own repeated listings stack as one presence.
    if (isDeclared(position.resource)) {
      needByResource.set(
        position.resource,
        (needByResource.get(position.resource) ?? 0) + 1,
      );
    } else {
      needByResource.set(position.resource, -1);
    }
  }
  for (const [resource, counted] of needByResource) {
    const need = counted === -1 ? 1 : counted;
    const occupied = Math.max(
      0,
      (slots.get(resource)?.size ?? 0) - (freedShares.get(resource) ?? 0),
    ) + plannedSharesOn(plans, resource);
    if (occupied + need > capacityFor(resource)) {
      return false;
    }
  }
  for (const node of group.quotaNeeds) {
    const def = quotaDefs.get(node);
    const limit = def === undefined ? Infinity : def.limit;
    let need = 0;
    for (const position of group.positions) {
      if (!position.granted && quotaChain(position.resource).includes(node)) {
        need += 1;
      }
    }
    const occupied = Math.max(
      0,
      (quotaUsed.get(node) ?? 0) - (freedQuota.get(node) ?? 0),
    ) + plannedQuotaAt(plans, node);
    if (occupied + need > limit) {
      return false;
    }
  }
  return true;
}

