  const b = registry.acquire({ resource: 'rootRes' }, 'b', 20);
  assert.deepEqual(
    ['leaf', 'mid', 'root'].map((n) => registry.quotaUsage(n)),
    [2, 2, 3],
  );

  clock.set(20);
  registry.release(b.token);
  assert.deepEqual(
    ['leaf', 'mid', 'root'].map((n) => registry.quotaUsage(n)),
