      ['parent', { limit: 2, parent: null }],
    ]),
    capacities: { r: { capacity: 5, quota: 'child' } },
  });
  registry.acquire('r', 'h');
  assert.throws(
    () => registry.acquire('r', 'g'),
    (e) => e.code === 'QUOTA_EXCEEDED' && e.quota === 'child',
  );
});

