import { createRegistry } from '/mnt/c/claude_gsb/cla12/solverB/task007/src/index.js';

function makeClk(start=0){let n=start;const c=()=>n;c.set=v=>{n=v};c.adv=d=>{n+=d};return c;}
const CFG = {
  quotas: { root: 6, m: { limit: 4, parent: 'root' }, n: { limit: 4, parent: 'root' } },
  capacities: {
    a: { capacity: 3, quota: 'm' },
    b: { capacity: 2, quota: 'm' },
    c: { capacity: 3, quota: 'n' },
    d: 2,
  },
};
const quotaOf = { a: ['m','root'], b: ['m','root'], c: ['n','root'], d: [] };
const capOf = { a:3,b:2,c:3,d:2 };

for (let seed = 1; seed <= 400; seed += 1) {
  let s = seed * 2654435761 % 2147483647;
  const rand = () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
  const pick = (arr) => arr[Math.floor(rand() * arr.length)];
  const clock = makeClk(0);
  const r = createRegistry({ ttlMs: 100, clock, ...CFG });
  // ledger: token -> {resource, expiresAt}; tickets for waiting groups
  const ledger = new Map();
  const tickets = [];
  const holders = [];
  function ledgerCounts(now) {
    const perResource = { a:0,b:0,c:0,d:0 };
    const perQuota = { root:0, m:0, n:0 };
    for (const t of ledger.values()) {
      // ledger only holds currently-issued, possibly expired-unswept shares;
      // caller sweeps first for live comparisons.
      perResource[t.resource] += 1;
      for (const q of quotaOf[t.resource]) perQuota[q] += 1;
    }
    return { perResource, perQuota };
  }
  function sweepLedger(now) {
    for (const [token, t] of [...ledger]) if (t.expiresAt <= now) ledger.delete(token);
  }
  function addGrants(grants, now) {
    for (const g of grants) {
      if (ledger.has(g.token)) throw new Error(`seed ${seed}: duplicate token ${g.token}`);
      ledger.set(g.token, { resource: g.resource, expiresAt: g.expiresAt });
    }
  }
  for (let step = 0; step < 120; step += 1) {
    const action = rand();
    if (action < 0.55) {
      // acquire 1..2 shares across 1..2 resources, sometimes waiting
      const resNames = ['a','b','c','d'];
      const k = 1 + Math.floor(rand()*2);
      const chosen = [];
      for (let i=0;i<k;i++){ const res=pick(resNames); const sh=1+Math.floor(rand()*2); for(let j=0;j<sh;j++) chosen.push(res); }
      const holder = `h${Math.floor(rand()*3)}`;
      const wait = rand() < 0.5 ? 1 + Math.floor(rand()*40) : undefined;
      let out;
      try {
        out = chosen.length === 1 && rand() < 0.5
          ? r.acquire(chosen[0], holder, 1+Math.floor(rand()*30), wait)
          : r.acquireAll(chosen, holder, 1+Math.floor(rand()*30), wait);
      } catch (e) {
        if (!['LEASE_TAKEN','QUOTA_EXCEEDED'].includes(e.code)) throw new Error(`seed ${seed}: bad code ${e.code}`);
        out = null;
      }
      if (out !== null) {
        if (Array.isArray(out)) {
          if (out.length !== chosen.length) throw new Error(`seed ${seed}: result length ${out.length} != ${chosen.length}`);
          addGrants(out, clock());
          // capacity invariant
          const {perResource} = ledgerCounts(clock());
          for (const res of new Set(chosen)) if (perResource[res] > capOf[res]) throw new Error(`seed ${seed}: capacity ${res} ${perResource[res]}>${capOf[res]}`);
          holders.push(...out);
        } else if (out.status === 'waiting') {
          tickets.push(out);
        } else if (typeof out.token === 'string') {
          addGrants([out], clock());
        } else {
          throw new Error(`seed ${seed}: weird result ${JSON.stringify(out)}`);
        }
      }
    } else if (action < 0.7) {
      const tokens = [...ledger.keys()];
      if (tokens.length) {
        const token = pick(tokens);
        const t = ledger.get(token);
        const ok = r.release(token);
        if (t.expiresAt > clock() && ok) ledger.delete(token);
      }
    } else if (action < 0.82) {
      clock.adv(1 + Math.floor(rand()*25));
      r.sweep();
      sweepLedger(clock());
    } else if (action < 0.9) {
      if (tickets.length) {
        const tk = pick(tickets);
        if (tk.status === 'waiting') {
          const ok = r.cancel(tk.waitId);
          if (!ok) throw new Error(`seed ${seed}: cancel of waiting ticket returned false`);
        }
      }
    } else {
      // expire waiters by advancing to/past a deadline then observing
      clock.adv(1 + Math.floor(rand()*45));
      r.stats();
    }

    // harvest any tickets that got granted since
    for (const tk of tickets) {
      if (tk.status === 'granted' && tk.leases) {
        addGrants(tk.leases, clock());
        const {perResource} = ledgerCounts(clock());
        for (const res of new Set(tk.leases.map(l=>l.resource))) {
          if (perResource[res] > capOf[res]) throw new Error(`seed ${seed}: wake capacity ${res}`);
        }
        tk.harvested = true;
      }
    }

    // after a sweep point, compare live counts and quota usage
    r.sweep();
    sweepLedger(clock());
    const { perResource, perQuota } = ledgerCounts(clock());
    const st = r.stats();
    const totalLedger = Object.values(perResource).reduce((a,b)=>a+b,0);
    if (st.live !== totalLedger) throw new Error(`seed ${seed} step ${step}: live ${st.live} != ledger ${totalLedger}`);
    for (const q of ['root','m','n']) {
      if (r.quotaUsage(q) !== perQuota[q]) throw new Error(`seed ${seed} step ${step}: quota ${q} ${r.quotaUsage(q)} != ${perQuota[q]}`);
      if (r.quotaUsage(q) > CFG.quotas[q === 'root' ? 'root' : q].limit
          && !(q !== 'root')) {
        // limit access below
      }
    }
    if (r.quotaUsage('root') > 6 || r.quotaUsage('m') > 4 || r.quotaUsage('n') > 4) {
      throw new Error(`seed ${seed}: quota over limit`);
    }
    if (st.granted !== st.live + st.released + st.reclaimed) {
      throw new Error(`seed ${seed}: counter identity ${JSON.stringify(st)}`);
    }
  }
}
